namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public List<int> Ratings { get; set; } = new();

    public double AverageRating => Ratings.Count > 0 ? Ratings.Average() : 0;
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Ingredients = "Pizza dough, San Marzano tomatoes, Fresh mozzarella, Fresh basil, Olive oil, Salt",
            Steps = "1. Preheat oven to 475°F.\n2. Roll out dough on floured surface.\n3. Spread crushed tomatoes evenly.\n4. Tear mozzarella and distribute.\n5. Bake 10-12 minutes until crust is golden.\n6. Top with fresh basil and drizzle olive oil.",
            Ratings = new List<int> { 5, 4, 5, 4 }
        },
        new Recipe
        {
            Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
            Ingredients = "Spaghetti, Guanciale, Eggs, Pecorino Romano, Black pepper",
            Steps = "1. Cook spaghetti in salted water.\n2. Crisp guanciale in a pan.\n3. Whisk eggs with grated pecorino and pepper.\n4. Toss hot pasta with guanciale.\n5. Remove from heat and stir in egg mixture.\n6. Serve immediately with extra pecorino.",
            Ratings = new List<int> { 5, 5, 4 }
        },
        new Recipe
        {
            Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
            Ingredients = "Chicken thighs, Yogurt, Garam masala, Tomato sauce, Heavy cream, Onion, Garlic, Ginger",
            Steps = "1. Marinate chicken in yogurt and spices for 2 hours.\n2. Grill or broil chicken until charred.\n3. Sauté onion, garlic, and ginger.\n4. Add tomato sauce and simmer.\n5. Stir in cream and garam masala.\n6. Add chicken pieces and simmer 10 minutes.",
            Ratings = new List<int> { 5, 4, 5 }
        },
        new Recipe
        {
            Id = 4, Title = "Vegetable Pad Thai", Category = "Asian",
            Ingredients = "Rice noodles, Tofu, Bean sprouts, Peanuts, Lime, Tamarind paste, Fish sauce, Sugar, Eggs",
            Steps = "1. Soak rice noodles in warm water.\n2. Mix tamarind paste, fish sauce, and sugar for sauce.\n3. Stir-fry tofu until golden.\n4. Scramble eggs in the pan.\n5. Add noodles and sauce, toss well.\n6. Top with bean sprouts, peanuts, and lime.",
            Ratings = new List<int> { 4, 4, 3 }
        },
        new Recipe
        {
            Id = 5, Title = "Beef Tacos", Category = "Mexican",
            Ingredients = "Ground beef, Taco shells, Lettuce, Tomato, Cheddar cheese, Sour cream, Cumin, Chili powder",
            Steps = "1. Season beef with cumin and chili powder.\n2. Brown beef in a skillet.\n3. Warm taco shells in oven.\n4. Dice lettuce and tomato.\n5. Assemble tacos with beef, toppings, and cheese.\n6. Serve with sour cream.",
            Ratings = new List<int> { 4, 5, 4 }
        },
        new Recipe
        {
            Id = 6, Title = "Chocolate Lava Cake", Category = "Desserts",
            Ingredients = "Dark chocolate, Butter, Eggs, Sugar, Flour, Vanilla extract",
            Steps = "1. Preheat oven to 425°F.\n2. Melt chocolate and butter together.\n3. Whisk eggs and sugar until thick.\n4. Fold in chocolate mixture and flour.\n5. Pour into greased ramekins.\n6. Bake 12-14 minutes until edges are set but center jiggles.",
            Ratings = new List<int> { 5, 5, 5, 4 }
        }
    };

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public IReadOnlyList<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe != null && stars >= 1 && stars <= 5)
            recipe.Ratings.Add(stars);
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Count > 0 ? _recipes.Max(r => r.Id) + 1 : 1;
        _recipes.Add(recipe);
    }
}

